sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({api, helpers
}) {

    var arr = [];
    // Replace 'look_up_records_1' with the exact name of your Look up records data resource
    var results = api.data.project_data_source.results;

    for (var i = 0; i < results.length; i++) {
        arr.push({
            // Replace 'sys_id' and 'name' with the Table fields you want to use
            id: results[i]._row_data.uniqueValue,
            label: results[i].name.value
        });
    }
    return arr;

}
